SELECT
    ,
    st.store_name AS storeName,
    w.warehouse_name AS warehouseName,
    eu.nickname AS userName


    s.is_deleted = 0


        AND (s.sale_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR s.remark LIKE CONCAT('%', #{q.keyword}, '%')
        OR st.store_name LIKE CONCAT('%', #{q.keyword}, '%'))


        AND s.store_id = #{q.storeId}


        AND s.warehouse_id = #{q.warehouseId}


        AND s.status = #{q.status}



        AND s.user_id = #{q.userId}


        AND s.create_time >= #{q.beginTime}


        AND s.create_time <= #{q.endTime}



ORDER BY s.id DESC

SELECT p.id, p.product_code, p.product_name, COALESCE(sk.sku_image, p.main_image) AS main_image, p.store_id, sk.id AS skuId, sk.spec_text AS specText, sk.product_price AS productPrice FROM shop_product_sku sk INNER JOIN shop_product p ON p.id = sk.product_id AND p.is_deleted = 0 WHERE sk.is_deleted = 0 AND sk.sale_enable = 1 AND p.store_id = #{storeId}
AND EXISTS (SELECT 1 FROM shop_erp_inventory i WHERE i.sku_id = sk.id AND i.warehouse_id = #{warehouseId} AND i.is_deleted = 0 AND i.stock - i.locked_stock > 0)
AND (p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.product_code LIKE CONCAT('%', #{keyword}, '%') OR sk.spec_text LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.id DESC, sk.id DESC LIMIT #{limit}
